"""Compare every generated byte with the exact commit under full oracle validation."""
import argparse
import hashlib
import json
import os
from pathlib import Path
import subprocess
import sys
import tarfile
import tempfile

BASE = '6b0130e2128fe1a188906c3eb8bab893f732bdef'
PREFIX = 'src/medcalc-bench-verified'


def manifest(path):
    return {str(p.relative_to(path)):hashlib.sha256(p.read_bytes()).hexdigest()
            for p in sorted(path.rglob('*')) if p.is_file()}


def main():
    parser=argparse.ArgumentParser()
    parser.add_argument('--output',type=Path,required=True)
    args=parser.parse_args()
    repo=Path(__file__).resolve().parents[3]
    with tempfile.TemporaryDirectory() as d:
        temp=Path(d)
        archive=temp/'base.tar'
        with archive.open('wb') as stream:
            subprocess.run(['git','archive',BASE,PREFIX],cwd=repo,stdout=stream,check=True)
        with tarfile.open(archive) as tar:
            tar.extractall(temp/'source',filter='data')
        for name,source in [('base',temp/'source'/PREFIX/'src'),('candidate',repo/PREFIX/'src')]:
            code='import medcalc_bench_verified.main as m; m.main()'
            subprocess.run([sys.executable,'-c',code,'--output-dir',str(temp/name)],cwd=temp,
                           env={**os.environ,'PYTHONPATH':str(source)},check=True,capture_output=True)
        baseline,candidate=manifest(temp/'base'),manifest(temp/'candidate')
        assert len(list((temp/'candidate').iterdir()))==1100
        differing=[k for k in set(baseline)|set(candidate) if baseline.get(k)!=candidate.get(k)]
        assert not differing, sorted(differing)[:20]
        digest=hashlib.sha256(json.dumps(candidate,sort_keys=True).encode()).hexdigest()
        report={'oracle_source_commit':BASE,'candidate_commit':subprocess.check_output(['git','rev-parse','HEAD'],cwd=repo,text=True).strip(),
                'candidate_worktree_dirty':bool(subprocess.check_output(['git','status','--porcelain'],cwd=repo,text=True).strip()),
                'cases':1100,'files_compared':len(candidate),'different_files':0,'manifest_sha256':digest,
                'note':'Only the full test split is compared. Native-agent and parity-subset integration are checked separately.'}
        with args.output.open('x') as handle:json.dump(report,handle,indent=2)
        print(json.dumps(report))


if __name__=='__main__':main()
